import{z as A,x as B,o as e,c as s,q as i,j as l,D as a,d as t,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"视觉编码器的服务化","description":"","frontmatter":{"title":"视觉编码器的服务化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-serving-vision-encoder.md","filePath":"llm/mm-serving-vision-encoder.md","lastUpdated":1791413859000}'),p={name:"llm/mm-serving-vision-encoder.md"};function m(d,E,h,c,D,C){const r=B("Mermaid");return e(),s("div",null,[E[2]||(E[2]=i('<h1 id="视觉编码器的服务化" tabindex="-1">视觉编码器的服务化 <a class="header-anchor" href="#视觉编码器的服务化" aria-label="Permalink to &quot;视觉编码器的服务化&quot;">​</a></h1><div class="epigraph"><p>视觉编码器不是语言模型里多出的一层，而是另一台机器：无状态、无 KV、一次前向；拿调度语言模型的方式调度它，两头都跑不满。</p><footer>—— 据 Dosovitskiy et al., ViT, ICLR 2021；Liu et al., LLaVA, 2023；Qwen2.5-VL Technical Report 与 vLLM 多模态服务实现整理</footer></div><p><a href="/llm/fw-contribution-map">上一课</a>把推理框架的贡献流程收成一条证据链：问题关复现、方案关定位、验证关数据、评审关回归，先组装证据再写代码。框架读透之后，这一栏转向负载侧的深钻——那套骨架的前提是输入清一色文本，缺口从请求带上第一张图开始：<a href="/llm/vision-encoder-pipeline">视觉编码器流水</a>已写过两段屋顶与串行等待的首 token 代价，本课把编码器当<strong>服务组件</strong>写：部署在哪、按什么单位批处理、怎么与语言模型 prefill 重叠、嵌入何时值得缓存。后课默认编码器已是可独立伸缩的池。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编码器的计算形态与语言模型只有一处相似：都是 Transformer 前向，差异决定调度。第一，无自回归：图像一次前向出全部 token，没有解码循环也没有 KV，算术强度高，是纯 compute-bound 负载。第二，形状动态：patch 数随分辨率平方变化，<a href="/llm/qwen-vl-naive-dynamic-res">原生动态分辨率</a>把「每张图多长」交给用户上传的像素，批内张量不再同形。第三，比例悬殊：聊天流量多数没有图，图文请求的编码又可能占首 token 延迟的一半。</p><p><span class="marginnote">「compute-bound」直译「受计算限制」：瓶颈在算力本身算不完，而不是在等显存搬运或等网络。这类负载能把 GPU 喂满，适合与「等显存」的解码负载错峰排班——就像费电的烤箱和费水洗衣机分时开，互不拖累。</span></p><p>部署形态由此成为选择题。同进程内嵌省掉序列化与网络跳，代价是形状多变的编码前向反复打断语言模型的 CUDA graph 与批调度，抢显存与 SM，故障也耦合；独立编码器池按自己的负载曲线扩缩容，代价是多一跳延迟，且两边模型版本必须显式配对。</p><h3 id="形状桶与重叠" tabindex="-1">形状桶与重叠 <a class="header-anchor" href="#形状桶与重叠" aria-label="Permalink to &quot;形状桶与重叠&quot;">​</a></h3><p>服务化把这两个问题各给一个答案。形状动态收进<strong>分辨率桶</strong>：预处理把图像缩到离散几档，桶内 padding 对齐，CUDA graph 按桶捕获一次反复重放；档位太细则组合爆炸，太粗则小图陪跑大图。串行等待靠<strong>重叠</strong>消除：编码器算请求 A 的图时，语言模型池同时跑请求 B 的 prefill，两段负载本就不该互相等待。</p><p><span class="marginnote">1024×1024 的图按 14px patch 切是 \\(74\\times74=5476\\) 个 patch，ViT 每层自注意力要算约三千万对相似度；512×512 只有 \\(37^2=1369\\) 个，注意力对数是前者的 \\(1/16\\)。分辨率桶的档位差在算力上是平方差，桶设计是性能工程。</span></p>',10)),(e(),l(o,null,{default:a(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%A4%9A%E6%A8%A1%E6%80%81%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20PP%5B%22%E9%A2%84%E5%A4%84%E7%90%86%E4%B8%8E%E5%88%86%E8%BE%A8%E7%8E%87%E5%88%86%E6%A1%B6%22%5D%0A%20%20PP%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E6%B1%A0%E6%8C%89%E6%A1%B6%E6%89%B9%E9%87%8F%E5%89%8D%E5%90%91%22%5D%0A%20%20ENC%20--%3E%20EMB%5B%22%E8%A7%86%E8%A7%89%E5%B5%8C%E5%85%A5%E9%98%9F%E5%88%97%22%5D%0A%20%20EMB%20--%3E%20HIT%7B%22%E5%B5%8C%E5%85%A5%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20HIT%20--%3E%7C%E6%98%AF%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%E7%BC%96%E7%A0%81%22%5D%0A%20%20HIT%20--%3E%7C%E5%90%A6%7C%20ENC%0A%20%20EMB%20--%3E%20LLM%5B%22%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%E6%B1%A0%E6%8B%BC%E5%85%A5%20prefill%22%5D%0A%20%20LLM%20--%3E%20DEC%5B%22%E9%80%90%20token%20%E8%A7%A3%E7%A0%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=i('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>嵌入缓存是编码器服务化独有的红利。同一张图会被反复请求，编码结果与请求文本无关，可按「图像内容 hash + 预处理参数 + 编码器版本」为键缓存嵌入；键里必须带后两者，缩放规则改一版旧嵌入全部作废，这一坑在<a href="/llm/mm-image-preprocess-batching">预处理批处理</a>展开。命中时请求直接从嵌入队列进入语言模型，首 token 延迟里整段编码时间清零。重叠的记账单位是流水段而不是请求：请求 \\(i\\) 的编码与请求 \\(j\\) 的 prefill 并行，吞吐由较慢一级封顶；容量规划分开问两个数——编码器每秒编码多少图、语言模型每秒 prefill 多少视觉 token，配比失衡时看各自利用率补卡。</p><p><span class="marginnote">嵌入缓存为什么成立？编码器只看图、不看你的问题——同一张图不管问「这是什么」还是「图里有几个人」，编码结果一模一样。所以键只需「图 + 预处理参数 + 编码器版本」，不必包含提问文本，命中天然与文本负载解耦。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>串行服务的首 token 延迟是 \\(T_{\\mathrm{ttft}}=T_{\\mathrm{enc}}+T_{\\mathrm{prefill}}\\)；重叠后单请求仍要等自己的编码完成，但系统吞吐趋于 \\(\\max\\) 而不是 \\(+\\)。重叠的前提是两段负载不同资源：编码器 compute-bound、解码 memory-bound，同卡混跑互相抢 SM，分池或分时片是把「不同资源」做实。编码器也因此不能共享语言模型那个<a href="/llm/continuous-batching">连续批处理</a>循环：解码每步几十毫秒的粒度，装不下一次几百毫秒、长度不定的编码前向。</p>',5)),(e(),l(o,null,{default:a(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%BC%96%E7%A0%81%E4%B8%8E%20prefill%20%E6%80%8E%E4%B9%88%E6%8E%92%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E4%B8%B2%E8%A1%8C%EF%BC%9A%E5%90%8C%E4%B8%80%E8%AF%B7%E6%B1%82%E5%85%88%E5%90%8E%E8%B7%91%22%7C%20SER%5B%22TTFT%20%3D%20T_enc%20%2B%20T_prefill%22%5D%0A%20%20Q%20--%3E%7C%22%E9%87%8D%E5%8F%A0%EF%BC%9AA%20%E7%9A%84%E7%BC%96%E7%A0%81%E5%B9%B6%E8%A1%8C%20B%20%E7%9A%84%20prefill%22%7C%20OVL%5B%22%E5%90%9E%E5%90%90%E8%B6%8B%E4%BA%8E%20max%20%E8%80%8C%E4%B8%8D%E6%98%AF%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20SER%20--%3E%20IDLE%5B%22%E4%B8%A4%E6%B1%A0%E8%BD%AE%E6%B5%81%E7%A9%BA%E9%97%B2%EF%BC%8C%E7%AE%97%E5%8A%9B%E7%99%BD%E7%AD%89%22%5D%0A%20%20OVL%20--%3E%20RES%5B%22%E5%89%8D%E6%8F%90%EF%BC%9A%E4%B8%A4%E6%AE%B5%E8%B4%9F%E8%BD%BD%E5%90%83%E4%B8%8D%E5%90%8C%E8%B5%84%E6%BA%90%22%5D%0A%20%20RES%20--%3E%20POOL%5B%22%E5%88%86%E6%B1%A0%E6%88%96%E5%88%86%E6%97%B6%E7%89%87%E6%8A%8A%E9%9A%94%E7%A6%BB%E5%81%9A%E5%AE%9E%22%5D%0A%20%20POOL%20--%3E%20WHY%5B%22%E8%A7%A3%E7%A0%81%E5%BE%AA%E7%8E%AF%E7%B2%92%E5%BA%A6%E8%A3%85%E4%B8%8D%E4%B8%8B%E7%BC%96%E7%A0%81%E5%89%8D%E5%90%91%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=i('<p>批处理动力学也不同。语言模型 decode 批越大越省带宽，编码批越大越省算力，但 padding 浪费随桶内方差增长。编码器没有 KV，批上限纯粹是激活显存，可以开得比解码激进得多，单位算力产出因此更高。</p><p><span class="marginnote">初学者容易以为「批越大越划算」对编码器无条件成立——实际上收益取决于桶内形状是否整齐：一批里大小图混杂时，小图要 padding 到最大形状「陪跑」，算力花在补零上。这就是先分桶再凑批、而不是无脑攒大批的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓存键的版本纪律是本课最脆的一环：预处理库升级、编码器微调、甚至浮点实现变化，都该让旧嵌入失效；漏任何一项，线上长期跑着新旧混合的嵌入，表现为能力退化而非报错。视频把编码器变成持续负载，池容量按稳态帧率规划，这留到<a href="/llm/mm-video-serving">视频理解的服务</a>；音频编码器按帧窗切分、形状固定，最好服务。分池也有代价：嵌入传输一图约几 MB，上规模后要进容量模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编码器是无自回归、无 KV、形状动态的 compute-bound 负载，调度单位与语言模型不同构。</li><li>形状桶加 CUDA graph 解决形状动态；桶档位是平方级的算力折中。</li><li>编码与 prefill 分属不同资源，重叠把 TTFT 从相加变成并行，吞吐封顶于较慢一级。</li><li>嵌入缓存键必须含图像内容、预处理参数与编码器版本，缺一即缓存漂移。</li><li>分池换来独立扩缩容与故障隔离，代价是嵌入传输带宽与版本配对纪律。</li><li>出处：据 ViT（Dosovitskiy et al., ICLR 2021）、LLaVA（Liu et al., 2023）、Qwen2.5-VL Technical Report（arXiv:2502.13923）与 vLLM 多模态服务实现整理。</li></ul>',6))])}const T=A(p,[["render",m]]);export{f as __pageData,T as default};
